    if (file) { try { dt.items.add(new (W.File || File)([file.svg], file.name, { type: 'image/svg+xml' })); } catch (e) { try { dt.items.add(new File([file.svg], file.name, { type: 'image/svg+xml' })); } catch (e2) { /* 渡せない */ } } }
