  /* ============================================================
   *  起動
   * ============================================================ */
  let raf = 0;
  function scan() { raf = 0; for (const m of document.querySelectorAll('.notion-media-menu')) processMenu(m); }
  function boot() {
    installCss();
    new MutationObserver((recs) => {
      if (raf) return;
      for (const r of recs) for (const n of r.addedNodes) if (n.nodeType === 1 && !(n.closest && n.closest('[data-c29]'))) { raf = requestAnimationFrame(scan); return; }
    }).observe(document.body, { childList: true, subtree: true });
    window.addEventListener('resize', () => { for (const m of document.querySelectorAll('.notion-media-menu')) { const M = MENUS.get(m); if (M && M.mode) placePanel(m, M); } });
    scan();
  }
  /* ページの準備ができてから（早く読まれた時も止まらないように） */
  if (document.body) boot(); else document.addEventListener('DOMContentLoaded', boot, { once: true });
